{"content": "// ── Redis Pub/Sub for real-time event broadcasting ──────────────────────────
// Singleton ioredis client + subscriber. The server's existing SSE routes still
// work via the in-process `clients` Set, but instead of polling the SQLite DB
// every 2-5 seconds they now receive every event as it happens through
// Pub/Sub, mirroring the trading bot's realtime pattern.
//
// Channels (all under the `jimesh:` namespace to avoid clashing with anything
// else on a shared Redis instance):
//   jimesh:routing:scores   — periodic model score snapshots (analytics feed)
//   jimesh:routing:decision — every successful routing decision (model+key+ms)
//   jimesh:routing:failure  — every model that failed on a request (no key, 429,
//                              upstream 5xx, cooldown, context too large, ...)
//   jimesh:key:cooldown     — every time a key is put on cooldown
//   jimesh:requests         — every request that completed (status, latency,
//                              input/output tokens) for the realtime monitor
//
// Graceful degradation: if Redis is unavailable at boot, every publish/subscribe
// call is a no-op. The rest of the server continues to function (SSE falls back
// to its existing in-process clients). The client reconnect logic takes care of
// recovering once Redis is back up — no manual restart required.

import IORedis, { type Redis as RedisClient, type RedisOptions } from 'ioredis';
import { logger } from '../lib/logger.js';

// Channels we publish on. Kept here so producers and the SSE bridge import the
// exact same strings and never silently disagree.
export const CHANNEL = {
  ROUTING_SCORES: 'jimesh:routing:scores',
  ROUTING_DECISION: 'jimesh:routing:decision',
  ROUTING_FAILURE: 'jimesh:routing:failure',
  KEY_COOLDOWN: 'jimesh:key:cooldown',
  REQUESTS: 'jimesh:requests',
} as const;

export type ChannelName = (typeof CHANNEL)[keyof typeof CHANNEL];

// Is the Pub/Sub layer wired up? Checked by callers that want to fail-safe
// without paying the cost of a try/catch on every publish.
let enabled = false;

// Status flag updated by the ioredis 'ready' / 'end' / 'error' events so other
// modules can show a connection indicator in the dashboard without re-running
// the connect logic.
let connected = false;

// Parsed once at boot. REDIS_ENABLED=false short-circuits the whole module so
// installs that don't have or don't want Redis (single-user localhost setups)
// can keep working unchanged.
function readConfig(): { url: string; enabled: boolean } {
  const url = process.env.REDIS_URL || 'redis://127.0.0.1:6379';
  const enabled = (process.env.REDIS_ENABLED ?? 'true').toLowerCase() !== 'false';
  return { url, enabled };
}

// Shared client options. Retry strategy caps the backoff at 2s so a Redis
// outage that recovers later doesn't keep the server waiting on an exponential
// delay curve.
function buildOptions(): RedisOptions {
  return {
    // Don't blow up boot if Redis is offline — ioredis queues commands and
    // reconnects in the background. The 'ready' / 'end' handlers flip the
    // `connected` flag so the rest of the app can react.
    enableOfflineQueue: true,
    maxRetriesPerRequest: 3,
    // Cap the reconnect backoff so a long Redis outage doesn't put us out for
    // minutes when it finally comes back.
    retryStrategy: (times) => Math.min(times * 200, 2000),
    // Don't print "ready" / "connect" / "error" on every reconnect — the
    // logger already records them, and ioredis's default is noisy.
    lazyConnect: false,
  };
}

let publisher: RedisClient | null = null;
let subscriber: RedisClient | null = null;

/**
 * Wire up the publisher and subscriber. Idempotent: a second call is a no-op
 * so it's safe to invoke from both index.ts (at boot) and any future hot-reload
 * path. Disables itself and returns gracefully if REDIS_ENABLED=false or the
 * initial connect fails — every publish then becomes a fire-and-forget no-op.
 */
export function initRedis(): void {
  if (publisher && subscriber) return; // already wired
  const { url, enabled: cfgEnabled } = readConfig();
  if (!cfgEnabled) {
    logger.info('[redis] REDIS_ENABLED=false — Pub/Sub disabled, SSE stays in-process');
    enabled = false;
    return;
  }

  enabled = true;
  try {
    publisher = new IORedis(url, buildOptions());
    subscriber = new IORedis(url, buildOptions());

    publisher.on('ready', () => {
      connected = true;
      logger.info(`[redis] publisher ready (${url})`);
    });
    publisher.on('end', () => {
      connected = false;
      logger.warn('[redis] publisher connection ended — will retry');
    });
    publisher.on('error', (err) => {
      // Suppress "ECONNREFUSED" spam when Redis is simply not running on the
      // local dev box — ioredis retries on its own.
      if ((err as NodeJS.ErrnoException)?.code !== 'ECONNREFUSED') {
        logger.warn(`[redis] publisher error: ${err.message}`);
      }
    });

    subscriber.on('ready', () => {
      logger.info(`[redis] subscriber ready (${url})`);
    });
    subscriber.on('end', () => {
      logger.warn('[redis] subscriber connection ended — will retry');
    });
    subscriber.on('error', (err) => {
      if ((err as NodeJS.ErrnoException)?.code !== 'ECONNREFUSED') {
        logger.warn(`[redis] subscriber error: ${err.message}`);
      }
    });
  } catch (err: any) {
    // A misformed REDIS_URL throws synchronously out of new IORedis(). Treat
    // it the same as a refused connection: log once and continue in disabled
    // mode.
    logger.warn(`[redis] failed to initialise — Pub/Sub disabled: ${err?.message ?? err}`);
    publisher = null;
    subscriber = null;
    enabled = false;
  }
}

/**
 * Stop the Pub/Sub client cleanly. Used by the server's shutdown handler so
 * a SIGTERM doesn't leave a half-open socket on the Redis side.
 */
export async function shutdownRedis(): Promise<void> {
  const p = publisher;
  const s = subscriber;
  publisher = null;
  subscriber = null;
  enabled = false;
  connected = false;
  await Promise.allSettled([
    p ? p.quit().catch(() => undefined) : Promise.resolve(),
    s ? s.quit().catch(() => undefined) : Promise.resolve(),
  ]);
}

/** Current connection state. Used by /api/health and the dashboard banner. */
export function getRedisStatus(): { enabled: boolean; connected: boolean; url: string } {
  return {
    enabled,
    connected,
    url: process.env.REDIS_URL || 'redis://127.0.0.1:6379',
  };
}

/**
 * Publish a JSON-serialisable payload on a channel. No-op when Pub/Sub is
 * disabled, the client isn't connected, or serialisation fails — the rest of
 * the routing path must NEVER throw because Redis is offline.
 */
export function publish(channel: ChannelName, payload: unknown): void {
  if (!enabled || !publisher || !connected) return;
  let json: string;
  try {
    json = JSON.stringify({ ts: Date.now(), data: payload });
  } catch {
    return; // circular ref, bigint, etc. — never crash the request path over telemetry
  }
  // ioredis's `publish` is async but we don't await — a dropped message on a
  // momentarily disconnected client is acceptable for telemetry. Fire-and-
  // forget keeps the call site a one-liner.
  publisher.publish(channel, json).catch(() => undefined);
}

/**
 * Subscribe to a channel. Multiple subscribers per channel are allowed; each
 * `handler` runs independently. Returns an unsubscribe function.
 *
 * Used by the SSE routes to forward Redis events straight to connected browser
 * clients. Same try/catch + null-check as publish so an outage here doesn't
 * take down the SSE handler.
 */
export function subscribe(channel: ChannelName, handler: (payload: any) => void): () => void {
  if (!enabled || !subscriber || !connected) {
    // No-op unsubscribe so callers can always call the return value cleanly.
    return () => undefined;
  }
  const messageHandler = (ch: string, message: string) => {
    if (ch !== channel) return;
    try {
      const envelope = JSON.parse(message);
      handler(envelope.data ?? envelope);
    } catch {
      // Bad JSON from a foreign publisher — ignore and keep the connection.
    }
  };
  subscriber.subscribe(channel).catch((err) => {
    logger.warn(`[redis] subscribe(${channel}) failed: ${err?.message ?? err}`);
  });
  subscriber.on('message', messageHandler);
  return () => {
    try {
      subscriber?.off('message', messageHandler);
      subscriber?.unsubscribe(channel).catch(() => undefined);
    } catch {
      // Subscriber may have been torn down already (shutdown). Swallow.
    }
  };
}
