{"content": "import { Router } from 'express';
import type { Request, Response } from 'express';
import { getDb } from '../db/index.js';
import { getRoutingScores } from '../services/router.js';
import { CHANNEL, publish, subscribe, getRedisStatus } from '../services/redis.js';

export const sseRouter = Router();

/**
 * Server-Sent Events for real-time analytics.
 *
 * Streaming strategy (mirrors the trading bot's pattern):
 *   1. Each route sets the SSE headers and adds the client to the in-process
 *      `clients` Set so legacy / direct callers still work.
 *   2. When Redis Pub/Sub is enabled, we also subscribe to the relevant channel
 *      and forward every event straight to the connected browser. That's the
 *      "realtime" path: no more 2-5s polling, the dashboard sees a new score
 *      the instant routing writes it.
 *   3. As a graceful fallback, a periodic timer keeps ticking even with Redis
 *      up so a missed message (network blip, pub/sub reconnect) still produces
 *      a fresh update. The interval is longer than the Redis path's effective
 *      latency (5s vs <100ms), so a healthy Redis install never hits the timer
 *      twice in a row.
 *   4. If Redis is unavailable the subscriptions are no-ops and the timer
 *      becomes the only feed — identical to the previous behaviour.
 */
const clients = new Set<Response>();

// Broadcast function for other parts of the app to send updates. Used by
// legacy in-process callers (e.g. proxy completion events) and by the Redis
// subscription handlers below.
export function broadcastSSE(event: string, data: any) {
  const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  clients.forEach((client) => {
    try {
      client.write(message);
    } catch (err) {
      clients.delete(client);
    }
  });
}

/** Best-effort SSE write — drops a client that has gone away. */
function safeWrite(res: Response, message: string) {
  try {
    res.write(message);
  } catch {
    clients.delete(res);
  }
}

/**
 * GET /sse/analytics
 * Streams routing analytics updates.
 */
sseRouter.get('/analytics', (req: Request, res: Response) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');

  clients.add(res);

  // Send initial data immediately so the dashboard renders before the first
  // Redis event arrives.
  try {
    const scores = getRoutingScores();
    safeWrite(res, `event: scores\ndata: ${JSON.stringify(scores)}\n\n`);
  } catch {
    /* silent fail */
  }

  // Redis realtime path: forward every score snapshot straight to the browser.
  // Also reflects the connection state in the very first event so the client
  // can show a "connected / disconnected" indicator without an extra round trip.
  const redisStatus = getRedisStatus();
  safeWrite(res, `event: redis_status\ndata: ${JSON.stringify(redisStatus)}\n\n`);

  const unsubscribe = subscribe(CHANNEL.ROUTING_SCORES, (payload) => {
    safeWrite(res, `event: scores\ndata: ${JSON.stringify(payload)}\n\n`);
  });

  // Polling fallback — only meaningful when Redis is down. With a healthy
  // Redis install this never fires because scores arrive within milliseconds.
  const interval = setInterval(() => {
    try {
      const scores = getRoutingScores();
      safeWrite(res, `event: scores\ndata: ${JSON.stringify(scores)}\n\n`);
    } catch {
      /* silent fail */
    }
  }, 5000);

  // Heartbeat every 30s so intermediate proxies don't kill the connection.
  const heartbeat = setInterval(() => {
    safeWrite(res, `: heartbeat\n\n`);
  }, 30000);

  req.on('close', () => {
    clearInterval(interval);
    clearInterval(heartbeat);
    unsubscribe();
    clients.delete(res);
    res.end();
  });
});

/**
 * GET /sse/models
 * Streams model-specific request events.
 */
sseRouter.get('/models', (req: Request, res: Response) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');

  clients.add(res);

  // Initial dump so the dashboard has something to render.
  try {
    const db = getDb();
    const recent = db.prepare(`
      SELECT
        r.id,
        r.created_at,
        r.platform,
        r.model_id,
        r.status,
        r.latency_ms,
        r.input_tokens,
        r.output_tokens
      FROM requests r
      WHERE r.created_at >= datetime('now', '-1 minute')
      ORDER BY r.created_at DESC
      LIMIT 50
    `).all();
    safeWrite(res, `event: requests\ndata: ${JSON.stringify(recent)}\n\n`);
  } catch {
    /* silent fail */
  }

  // Realtime: every routed request fires a `jimesh:requests` event; the polling
  // fallback below only matters when Redis is offline.
  const unsubscribe = subscribe(CHANNEL.REQUESTS, (payload) => {
    safeWrite(res, `event: requests\ndata: ${JSON.stringify([payload])}\n\n`);
  });

  const interval = setInterval(() => {
    try {
      const db = getDb();
      const recent = db.prepare(`
        SELECT
          r.id,
          r.created_at,
          r.platform,
          r.model_id,
          r.status,
          r.latency_ms,
          r.input_tokens,
          r.output_tokens
        FROM requests r
        WHERE r.created_at >= datetime('now', '-1 minute')
        ORDER BY r.created_at DESC
        LIMIT 50
      `).all();

      safeWrite(res, `event: requests\ndata: ${JSON.stringify(recent)}\n\n`);
    } catch {
      /* silent fail */
    }
  }, 3000);

  const heartbeat = setInterval(() => {
    safeWrite(res, `: heartbeat\n\n`);
  }, 30000);

  req.on('close', () => {
    clearInterval(interval);
    clearInterval(heartbeat);
    unsubscribe();
    clients.delete(res);
    res.end();
  });
});

/**
 * GET /sse/traces
 * Streams routing decision / failure trace events.
 */
sseRouter.get('/traces', (req: Request, res: Response) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');

  clients.add(res);

  // Initial dump so the panel shows recent failures immediately.
  try {
    const db = getDb();
    const traces = db.prepare(`
      SELECT
        r.id,
        r.created_at,
        r.platform,
        r.model_id,
        r.status,
        r.error_type,
        r.latency_ms
      FROM requests r
      WHERE r.created_at >= datetime('now', '-30 seconds')
      ORDER BY r.created_at DESC
      LIMIT 20
    `).all();
    safeWrite(res, `event: traces\ndata: ${JSON.stringify(traces)}\n\n`);
  } catch {
    /* silent fail */
  }

  // Realtime: a routing decision fires `jimesh:routing:decision`, a failed
  // attempt fires `jimesh:routing:failure`. Forward both as `traces` so the
  // frontend doesn't have to know there are two channels.
  const unsubDecision = subscribe(CHANNEL.ROUTING_DECISION, (payload) => {
    safeWrite(res, `event: traces\ndata: ${JSON.stringify([{ ...payload, kind: 'decision' }])}\n\n`);
  });
  const unsubFailure = subscribe(CHANNEL.ROUTING_FAILURE, (payload) => {
    safeWrite(res, `event: traces\ndata: ${JSON.stringify([{ ...payload, kind: 'failure' }])}\n\n`);
  });

  const interval = setInterval(() => {
    try {
      const db = getDb();
      const traces = db.prepare(`
        SELECT
          r.id,
          r.created_at,
          r.platform,
          r.model_id,
          r.status,
          r.error_type,
          r.latency_ms
        FROM requests r
        WHERE r.created_at >= datetime('now', '-30 seconds')
        ORDER BY r.created_at DESC
        LIMIT 20
      `).all();
      safeWrite(res, `event: traces\ndata: ${JSON.stringify(traces)}\n\n`);
    } catch {
      /* silent fail */
    }
  }, 2000);

  const heartbeat = setInterval(() => {
    safeWrite(res, `: heartbeat\n\n`);
  }, 30000);

  req.on('close', () => {
    clearInterval(interval);
    clearInterval(heartbeat);
    unsubDecision();
    unsubFailure();
    clients.delete(res);
    res.end();
  });
});

/**
 * GET /sse/monitor
 * Unified realtime monitor feed — every routing decision, failure, request
 * and key cooldown in one place. Used by the operator dashboard's live view.
 */
sseRouter.get('/monitor', (req: Request, res: Response) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no');

  clients.add(res);

  // Send connection state on connect so the UI can render an indicator.
  safeWrite(res, `event: redis_status\ndata: ${JSON.stringify(getRedisStatus())}\n\n`);

  const unsubs: Array<() => void> = [];
  unsubs.push(subscribe(CHANNEL.ROUTING_DECISION, (p) => {
    safeWrite(res, `event: routing_decision\ndata: ${JSON.stringify(p)}\n\n`);
  }));
  unsubs.push(subscribe(CHANNEL.ROUTING_FAILURE, (p) => {
    safeWrite(res, `event: routing_failure\ndata: ${JSON.stringify(p)}\n\n`);
  }));
  unsubs.push(subscribe(CHANNEL.KEY_COOLDOWN, (p) => {
    safeWrite(res, `event: key_cooldown\ndata: ${JSON.stringify(p)}\n\n`);
  }));
  unsubs.push(subscribe(CHANNEL.REQUESTS, (p) => {
    safeWrite(res, `event: request\ndata: ${JSON.stringify(p)}\n\n`);
  }));

  const heartbeat = setInterval(() => {
    safeWrite(res, `: heartbeat\n\n`);
  }, 30000);

  req.on('close', () => {
    clearInterval(heartbeat);
    for (const u of unsubs) u();
    clients.delete(res);
    res.end();
  });
});

// Re-export so other modules can publish score snapshots after a relevant
// change (cooldown expires, key status flips) without re-importing the channel
// constant.
export { CHANNEL, publish, getRedisStatus };
