const clients = new Set<Response>();

// Broadcast function for other parts of the app to send updates. Used by
// legacy in-process callers (e.g. proxy completion events) and by the Redis
// subscription handlers below.
export function broadcastSSE(event: string, data: any) {
  const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
  clients.forEach((client) => {
    try {
      client.write(message);
    } catch (err) {
      clients.delete(client);
    }
  });
}

/** Best-effort SSE write — drops a client that has gone away. */
function safeWrite(res: Response, message: string) {
  try {
    res.write(message);
  } catch {
    clients.delete(res);
  }
}

/**
