  res.setHeader('X-Accel-Buffering', 'no');

  clients.add(res);

  // Send initial data immediately so the dashboard renders before the first
  // Redis event arrives.
  try {
    const scores = getRoutingScores();
    safeWrite(res, `event: scores\ndata: ${JSON.stringify(scores)}\n\n`);
  } catch {
    /* silent fail */
  }

  // Redis realtime path: forward every score snapshot straight to the browser.
  // Also reflects the connection state in the very first event so the client
  // can show a "connected / disconnected" indicator without an extra round trip.
  const redisStatus = getRedisStatus();
  safeWrite(res, `event: redis_status\ndata: ${JSON.stringify(redisStatus)}\n\n`);

  const unsubscribe = subscribe(CHANNEL.ROUTING_SCORES, (payload) => {
    safeWrite(res, `event: scores\ndata: ${JSON.stringify(payload)}\n\n`);
  });

  // Polling fallback — only meaningful when Redis is down. With a healthy
  // Redis install this never fires because scores arrive within milliseconds.
  const interval = setInterval(() => {
    try {
      const scores = getRoutingScores();
      safeWrite(res, `event: scores\ndata: ${JSON.stringify(scores)}\n\n`);
    } catch {
      /* silent fail */
    }
  }, 5000);

  // Heartbeat every 30s so intermediate proxies don't kill the connection.
  const heartbeat = setInterval(() => {
    safeWrite(res, `: heartbeat\n\n`);
  }, 30000);

  req.on('close', () => {
    clearInterval(interval);
    clearInterval(heartbeat);
    unsubscribe();
    clients.delete(res);
    res.end();
  });
});

