import { Router } from 'express';
import { providerHealth } from '../services/providerHealth.js';
import { requireAuth } from '../middleware/requireAuth.js';
export const providerHealthRouter = Router();
// All routes require authentication
providerHealthRouter.use(requireAuth);
// GET /api/health/providers - All providers health
providerHealthRouter.get('/providers', async (_req, res) => {
    try {
        const reports = await providerHealth.checkAll();
        res.json(reports);
    }
    catch (error) {
        console.error('[Health] Check all providers failed:', error);
        res.status(500).json({ error: { message: 'Health check failed' } });
    }
});
// GET /api/health/provider/:platform - Specific provider health
providerHealthRouter.get('/provider/:platform', async (req, res) => {
    try {
        const platform = Array.isArray(req.params.platform) ? req.params.platform[0] : req.params.platform;
        const baseUrl = req.query.baseUrl;
        const status = await providerHealth.checkProvider(platform, baseUrl);
        res.json(status);
    }
    catch (error) {
        console.error('[Health] Check provider failed:', error);
        res.status(500).json({ error: { message: 'Health check failed' } });
    }
});
// GET /api/health/uptime/:platform - Uptime stats
providerHealthRouter.get('/uptime/:platform', (req, res) => {
    try {
        const platform = Array.isArray(req.params.platform) ? req.params.platform[0] : req.params.platform;
        const period = req.query.period || 'day';
        const baseUrl = req.query.baseUrl;
        const stats = providerHealth.getUptime(platform, period, baseUrl);
        res.json(stats);
    }
    catch (error) {
        console.error('[Health] Get uptime failed:', error);
        res.status(500).json({ error: { message: 'Failed to get uptime stats' } });
    }
});
// POST /api/health/check - Trigger health check for all providers
providerHealthRouter.post('/check', async (_req, res) => {
    try {
        const reports = await providerHealth.checkAll();
        res.json({ success: true, reports });
    }
    catch (error) {
        console.error('[Health] Manual check failed:', error);
        res.status(500).json({ error: { message: 'Health check failed' } });
    }
});
// GET /api/health/history - Health check history (optionally filtered by platform)
providerHealthRouter.get('/history', (req, res) => {
    try {
        const platform = req.query.platform;
        const limit = parseInt(req.query.limit, 10) || 100;
        const history = providerHealth.getHistory(platform, limit);
        res.json(history);
    }
    catch (error) {
        console.error('[Health] Get history failed:', error);
        res.status(500).json({ error: { message: 'Failed to get history' } });
    }
});
// POST /api/health/monitor/start - Start continuous monitoring
providerHealthRouter.post('/monitor/start', (req, res) => {
    try {
        const intervalMs = parseInt(req.query.intervalMs, 10) || 5 * 60 * 1000;
        providerHealth.startMonitoring(intervalMs);
        res.json({ success: true, message: 'Monitoring started' });
    }
    catch (error) {
        console.error('[Health] Start monitoring failed:', error);
        res.status(500).json({ error: { message: 'Failed to start monitoring' } });
    }
});
